INSERT INTO teachers (id, name, department_id, designation, bio) VALUES
  ('30000000-0000-0000-0000-000000000001', 'Dr. Ahmed Khan', '20000000-0000-0000-0000-000000000001', 'Professor', 'Dr. Ahmed Khan is a seasoned professor with over 15 years of experience in Mechanical Engineering.'),
  ('30000000-0000-0000-0000-000000000002', 'Prof. Sara Malik', '20000000-0000-0000-0000-000000000005', 'Professor', 'Prof. Sara Malik is a dedicated educator in the Faculty of Pharmacy, specializing in pharmaceutical chemistry.'),
  ('30000000-0000-0000-0000-000000000003', 'Dr. Zainab Ali', '20000000-0000-0000-0000-000000000008', 'Associate Professor', 'Dr. Zainab Ali brings extensive industry experience to the classroom, specializing in Strategic Management.'),
  ('30000000-0000-0000-0000-000000000004', 'Dr. Usman Raza', '20000000-0000-0000-0000-000000000003', 'Professor', 'Dr. Usman Raza is an expert in Structural Engineering and Project Management.'),
  ('30000000-0000-0000-0000-000000000005', 'Prof. Fatima Hassan', '20000000-0000-0000-0000-000000000019', 'Lecturer', 'Prof. Fatima Hassan is a patient and thorough educator specializing in Biology.'),
  ('30000000-0000-0000-0000-000000000006', 'Dr. Bilal Ahmed', '20000000-0000-0000-0000-000000000024', 'Associate Professor', 'Dr. Bilal Ahmed is an articulate and insightful professor of Law, specializing in Constitutional Law.'),
  ('30000000-0000-0000-0000-000000000007', 'Dr. Hira Rashid', '20000000-0000-0000-0000-000000000011', 'Professor', 'Dr. Hira Rashid specializes in Data Structures, Algorithms, and Artificial Intelligence.'),
  ('30000000-0000-0000-0000-000000000008', 'Prof. Omar Farooq', '20000000-0000-0000-0000-000000000002', 'Associate Professor', 'Prof. Omar Farooq specializes in Power Systems and Renewable Energy.'),
  ('30000000-0000-0000-0000-000000000009', 'Dr. Nadia Pervaiz', '20000000-0000-0000-0000-000000000009', 'Associate Professor', 'Dr. Nadia Pervaiz has over a decade of experience in Accounting and Financial Management.'),
  ('30000000-0000-0000-0000-000000000010', 'Prof. Kamal Javed', '20000000-0000-0000-0000-000000000012', 'Lecturer', 'Prof. Kamal Javed is an expert in Full-Stack Development and Software Architecture.'),
  ('30000000-0000-0000-0000-000000000011', 'Dr. Ayesha Tariq', '20000000-0000-0000-0000-000000000022', 'Professor', 'Dr. Ayesha Tariq specializes in Pure and Applied Mathematics.'),
  ('30000000-0000-0000-0000-000000000012', 'Prof. Hassan Raza', '20000000-0000-0000-0000-000000000010', 'Associate Professor', 'Prof. Hassan Raza teaches Marketing Strategy and Consumer Behavior.'),
  ('30000000-0000-0000-0000-000000000013', 'Dr. Mariam Sheikh', '20000000-0000-0000-0000-000000000023', 'Lecturer', 'Dr. Mariam Sheikh focuses on Environmental Impact Assessment and Climate Change.'),
  ('30000000-0000-0000-0000-000000000014', 'Prof. Imran Hussain', '20000000-0000-0000-0000-000000000013', 'Professor', 'Prof. Imran Hussain is a leader in Big Data Analytics and Machine Learning.'),
