  ('30000000-0000-0000-0000-000000000018', 'Prof. Usman Ali', '20000000-0000-0000-0000-000000000004', 'Professor', 'Prof. Usman Ali researches Process Engineering and Nanotechnology.'),
  ('30000000-0000-0000-0000-000000000019', 'Dr. Sara Zafar', '20000000-0000-0000-0000-000000000007', 'Lecturer', 'Dr. Sara Zafar teaches Clinical Pharmacology and Therapeutics.'),
  ('30000000-0000-0000-0000-000000000020', 'Prof. Faisal Mehmood', '20000000-0000-0000-0000-000000000025', 'Associate Professor', 'Prof. Faisal Mehmood specializes in International Political Economy.'),
