INSERT INTO teacher_reviews (teacher_id, reviewer_name, rating, review_text, upvotes, downvotes, created_at) VALUES
  ('30000000-0000-0000-0000-000000000001', 'Ali R.', 5, 'One of the best professors I have ever had. His explanations are crystal clear.', 23, 1, '2024-12-15T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000001', 'Hira S.', 4, 'Very knowledgeable and helpful during office hours. Exams are challenging but fair.', 15, 2, '2024-11-20T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000001', 'Omar K.', 5, 'Dr. Khan makes complex topics easy to understand. Highly recommended!', 31, 0, '2024-10-05T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000002', 'Nadia P.', 5, 'Prof. Malik is incredibly passionate about pharmacy. Her lectures are engaging.', 28, 0, '2024-12-10T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000002', 'Kamal J.', 5, 'Best pharmacy professor! She makes lab work exciting.', 19, 1, '2024-11-28T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000003', 'Fatima N.', 4, 'Dr. Ali is very professional and organized. Her class requires dedication.', 11, 3, '2024-12-01T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000003', 'Raza M.', 4, 'Strict but fair. She prepares you well for the corporate world.', 8, 1, '2024-11-15T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000004', 'Imran A.', 5, 'Dr. Raza is a true mentor. He pushes you to think beyond the textbook.', 25, 0, '2024-12-18T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000004', 'Sana T.', 4, 'Challenging courses but incredibly rewarding.', 14, 2, '2024-11-22T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000005', 'Ayesha K.', 4, 'Very approachable and always willing to help. Lab sessions are well-organized.', 9, 1, '2024-12-05T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000006', 'Hassan N.', 5, 'Dr. Ahmed makes law fascinating. His court case analyses are brilliant.', 27, 0, '2024-12-12T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000006', 'Mariam Q.', 5, 'Fair grader and incredibly knowledgeable. Every lecture is a masterclass.', 22, 1, '2024-11-30T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000006', 'Saad R.', 4, 'Highly articulate and fair. He respects different viewpoints.', 16, 2, '2024-10-20T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000007', 'Bilal K.', 5, 'Dr. Rashid is a genius. Her DSA course is the best in the university.', 35, 1, '2024-12-20T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000008', 'Zara L.', 3, 'Knowledgeable but the lectures can be quite dry. Needs more practical examples.', 5, 8, '2024-11-10T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000009', 'Usman G.', 4, 'Dr. Pervaiz makes accounting interesting. Her examples are very practical.', 13, 2, '2024-12-08T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000014', 'Fahad M.', 5, 'Prof. Hussain is a data science wizard. His projects are industry-relevant.', 29, 0, '2024-12-22T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000014', 'Laiba S.', 4, 'Great teacher but the workload is very heavy. You will learn a lot though.', 17, 3, '2024-12-01T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000022', 'Farhan A.', 5, 'Prof. Mahmood makes physics fascinating. His derivations are always clear.', 21, 1, '2024-12-15T10:00:00Z'),
  ('30000000-0000-0000-0000-000000000030', 'Mehwish R.', 4, 'Prof. Sheikh brings real corporate experience to the classroom. Very insightful.', 12, 1, '2024-11-25T10:00:00Z');
