INSERT INTO memories (title, description, latitude, longitude, submitted_by_name, likes, status, created_at) VALUES
  ('Sunset from Engineering Block', 'Absolutely breathtaking sunset view from the top floor of the Engineering Block!', 31.3930, 74.2435, 'Ahmed K.', 42, 'approved', '2024-12-15T16:30:00Z'),
  ('Pharmacy Lab Session', 'Amazing practical session today — synthesized a new compound!', 31.3928, 74.2428, 'Sara M.', 28, 'approved', '2024-12-10T14:00:00Z'),
  ('Business Competition Win', 'Won the annual business case competition! So proud of our team!', 31.3918, 74.2432, 'Zainab A.', 56, 'approved', '2024-12-05T12:00:00Z'),
  ('Late Night Coding', 'Late night debugging session in the CS lab. Finally fixed that bug!', 31.3925, 74.2425, 'Usman R.', 35, 'approved', '2024-11-28T23:00:00Z'),
  ('Library Marathon', 'Pulled an all-nighter at the library before finals. Worth it!', 31.3922, 74.2435, 'Fatima H.', 71, 'approved', '2024-11-20T08:00:00Z'),
  ('Spring Festival', 'The annual spring festival on the Science Block lawn was incredible!', 31.3915, 74.2428, 'Bilal A.', 63, 'approved', '2024-11-15T15:00:00Z'),
  ('First Day at UOL', 'First day at university — nervous but so excited for this journey!', 31.3924, 74.2430, 'New Student', 89, 'approved', '2024-10-01T09:00:00Z'),
  ('Graduation Photoshoot', 'Best friends graduation photoshoot at the Admin Block lawn!', 31.3927, 74.2432, 'Hira R.', 45, 'approved', '2024-09-20T17:00:00Z'),
  ('Cricket Match Victory', 'Won the inter-department cricket tournament at the sports complex!', 31.3910, 74.2435, 'Team CS', 78, 'approved', '2024-11-10T16:00:00Z'),
  ('Farewell Party', 'An emotional farewell party for our seniors in the auditorium.', 31.3913, 74.2435, 'Amina S.', 52, 'approved', '2024-06-15T19:00:00Z'),
  ('Research Conference', 'Presented my research paper at the annual CS conference. Great feedback!', 31.3924, 74.2420, 'Dr. Samia', 34, 'approved', '2024-10-20T11:00:00Z'),
  ('Rainy Day at Campus', 'The campus looks magical in the rain. Captured this from the library window.', 31.3922, 74.2435, 'Rain Lover', 67, 'approved', '2024-08-12T15:30:00Z'),
  ('New Mural at Science Block', 'Check out the new science mural near the Biology department! Needs approval.', 31.3915, 74.2428, 'Art Club', 0, 'pending', '2025-01-10T10:00:00Z'),
  ('Lost and Found: Calculator', 'Found a scientific calculator in PB-101. Contact me to claim!', 31.3928, 74.2428, 'Fahad M.', 0, 'pending', '2025-01-12T14:00:00Z'),
  ('Study Group Forming', 'Looking for study partners for the upcoming Data Science exams!', 31.3925, 74.2425, 'Laiba K.', 0, 'pending', '2025-01-15T16:00:00Z');
